"""Rabin-Miller test.

    n should be odd number and 1 < b < n-1.
    """
def spsp(n: Any, a: Any) -> object {
    if ((n % 2) == 0) {
        return False;
    }
    n1 = n - 1;
    d = n1;
    r = 1;
    s = 0;
    while (r != 0) {
        r = d % 2;
        d = d // 2;
        s += 1;
    }
    p = a;
    p = pow(p, d, n);
    if ((p == 1) or (p == n1)) {
        return True;
    }
    for i in range(1, s) {
        p = pow(p, 2, n);
        if (p == n1) {
            return True;
        }
    }
    return False;
}

